const config = {
  "previewFeatures": [],
  "clientVersion": "7.2.0",
  "engineVersion": "0c8ef2ce45c83248ab3df073180d5eda9e8be7a3",
  "activeProvider": "postgresql",
  "inlineSchema": "generator client {\n  provider   = \"prisma-client-js\"\n  output     = \"../lib/generated/prisma\"\n  engineType = \"library\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n/**\n * Consolidated messaging schema:\n * - Replaced BeneficiaryMessage, BeneficiaryRequest, BeneficiaryRequestResponse\n * with Message and Response.\n * - Message.messageKind tags origin/intent: beneficiary, request, system, external,\n * go_girls_ict_team, testimonial.\n * External = visitor; visitors can create Message but (for now) cannot create Responses.\n * - Response is used for replies and is authored by a User, a Beneficiary, or the System.\n * - Message.allowResponses toggles whether replies are allowed per-message (useful for external messages).\n * - Message.senderEmail / senderIp store visitor metadata when messageKind = external.\n */\nmodel HomePage {\n  id         Int      @id @default(autoincrement())\n  heroVideo  String\n  vision     String\n  mission    String\n  focus      String\n  coreValues String\n  about      String? // new\n  logo       String? // new\n  banner     String? // new\n  siteName   String? // new\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n}\n\nmodel Project {\n  id            Int                  @id @default(autoincrement())\n  title         Json // Tiptap JSON doc (edited/viewed via components/editor/*)\n  slug          String               @unique\n  content       Json\n  images        String[]\n  projectStatus Status\n  publishStatus PublishStatus        @default(draft)\n  createdAt     DateTime             @default(now())\n  updatedAt     DateTime             @updatedAt\n  createdById   String\n  updatedById   String?\n  approvedById  String?\n  approvedBy    User?                @relation(\"ProjectApprovedBy\", fields: [approvedById], references: [id])\n  createdBy     User                 @relation(\"ProjectCreatedBy\", fields: [createdById], references: [id])\n  updatedBy     User?                @relation(\"ProjectUpdatedBy\", fields: [updatedById], references: [id])\n  reports       Report[]\n  events        Event[]\n  beneficiaries BeneficiaryProject[]\n  talkshows     RadioTalkshow[]\n  podcasts      Podcast[]\n}\n\nmodel Report {\n  id            Int                 @id @default(autoincrement())\n  title         String\n  slug          String              @unique\n  images        String[]\n  files         String[]\n  publishStatus PublishStatus       @default(draft)\n  accessCount   Int                 @default(0)\n  downloadCount Int                 @default(0)\n  createdAt     DateTime            @default(now())\n  updatedAt     DateTime            @updatedAt\n  createdById   String\n  updatedById   String?\n  approvedById  String?\n  projectId     Int? // many-to-one with Project\n  approvedBy    User?               @relation(\"ReportApprovedBy\", fields: [approvedById], references: [id])\n  createdBy     User                @relation(\"ReportCreatedBy\", fields: [createdById], references: [id])\n  project       Project?            @relation(fields: [projectId], references: [id])\n  updatedBy     User?               @relation(\"ReportUpdatedBy\", fields: [updatedById], references: [id])\n  events        Event[]\n  beneficiaries BeneficiaryReport[]\n  talkshows     RadioTalkshow[]\n  podcasts      Podcast[]\n}\n\nmodel Podcast {\n  id            Int           @id @default(autoincrement())\n  title         Json // Tiptap JSON doc (edited/viewed via components/editor/*)\n  slug          String        @unique\n  description   Json // Tiptap JSON doc (edited/viewed via components/editor/*)\n  image         String? // illustration / cover artwork (card thumbnail)\n  poster        String? // wide banner used as the /resources page hero when this is the latest published podcast\n  audioUrl      String // mp3 path under public/assets/audio/podcasts\n  waveform      Float[]       @default([]) // precomputed amplitude peaks (0..1) for the waveform UI\n  publishedAt   DateTime      @default(now())\n  publishStatus PublishStatus @default(draft)\n  accessCount   Int           @default(0) // play count\n  createdAt     DateTime      @default(now())\n  updatedAt     DateTime      @updatedAt\n  createdById   String\n  updatedById   String?\n  approvedById  String?\n  approvedBy    User?         @relation(\"PodcastApprovedBy\", fields: [approvedById], references: [id])\n  createdBy     User          @relation(\"PodcastCreatedBy\", fields: [createdById], references: [id])\n  updatedBy     User?         @relation(\"PodcastUpdatedBy\", fields: [updatedById], references: [id])\n\n  // Beneficiaries who took part in / are featured on this podcast episode.\n  beneficiaries BeneficiaryPodcast[]\n\n  // \"By\": who hosted/appeared on this episode — see HostType above.\n  hostType          HostType?\n  hostBeneficiaryId String?\n  hostBeneficiary   Beneficiary? @relation(\"PodcastHostBeneficiary\", fields: [hostBeneficiaryId], references: [id])\n  hostUserId        String?\n  hostUser          User?        @relation(\"PodcastHostUser\", fields: [hostUserId], references: [id])\n  hostFirstName     String?\n  hostLastName      String?\n\n  // Optional single links to other content this podcast relates to.\n  projectId Int?\n  project   Project? @relation(fields: [projectId], references: [id])\n\n  eventId Int?\n  event   Event? @relation(fields: [eventId], references: [id])\n\n  reportId Int?\n  report   Report? @relation(fields: [reportId], references: [id])\n\n  institutionId String?\n  institution   Institution? @relation(fields: [institutionId], references: [id])\n\n  // Optional link to a Radio Talkshow this podcast episode is tied to (see\n  // RadioTalkshow.podcasts for the reverse side).\n  talkshowId Int?\n  talkshow   RadioTalkshow? @relation(fields: [talkshowId], references: [id])\n}\n\nenum MessageCategory {\n  beneficiary\n  request\n  system\n  external\n  go_girls_ict_team\n  testimonial\n}\n\nmodel Message {\n  id              Int             @id @default(autoincrement())\n  title           Json? // Tiptap JSON doc (edited/viewed via components/editor/*)\n  affiliated      String?\n  name            String?\n  content         Json\n  nameImageUrl    String?\n  messageImageUrl String?\n  messageStatus   PublishStatus   @default(draft)\n  messageCategory MessageCategory @default(external)\n\n  // Visitor metadata (useful when messageCategory = external)\n  senderEmail String?\n  senderIp    String?\n\n  // Toggle whether replies are allowed for this message (default true).\n  allowResponses Boolean @default(true)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Optional relations: messages can be created/updated/approved by a User (or be system/external)\n  createdById  String?\n  updatedById  String?\n  approvedById String?\n\n  createdBy User? @relation(\"MessageCreatedBy\", fields: [createdById], references: [id])\n  updatedBy User? @relation(\"MessageUpdatedBy\", fields: [updatedById], references: [id])\n  approver  User? @relation(\"MessageApprovedBy\", fields: [approvedById], references: [id])\n\n  // if this message is tied to a Beneficiary (testimonial, request), point to them\n  beneficiaryId String?\n  beneficiary   Beneficiary? @relation(\"BeneficiaryMessages\", fields: [beneficiaryId], references: [id])\n\n  // replies to this message\n  responses Response[]\n\n  @@map(\"Message\")\n}\n\n// Prisma schema: User + user-related models (PasswordHistory, PasswordChangeLog,\n// FailedLoginAttempt, Session) — with relation fields re-introduced on User model.\n\nenum Role {\n  super // Full control, including creating and deleting users\n  admin // Broad management, except creating and deleting users\n  moderator // can manage and moderate content\n  beneficiary // can manage their own profile and requests\n  guest // can only view published content\n}\n\nenum LoginStatus {\n  active\n  inactive\n}\n\nmodel User {\n  id        String   @id @default(cuid())\n  firstName String?\n  lastName  String?\n  username  String   @unique\n  password  String\n  email     String?  @unique\n  image     String?\n  role      Role     @default(guest)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // New profile & login fields\n  about       String? // brief biography\n  lastLogin   DateTime? // last successful login time\n  loginStatus LoginStatus @default(inactive) // active | inactive\n\n  // Rate limit / lockout helpers\n  failedLoginCount Int       @default(0)\n  lockedUntil      DateTime?\n\n  // User-centric auth/session/history relations\n  passwordHistory   PasswordHistory[]\n  passwordChangeLog PasswordChangeLog[]\n  failedLogins      FailedLoginAttempt[]\n  sessions          Session[]\n\n  // ----- domain relations  -----\n  // Messages\n  approvedMessages Message[] @relation(\"MessageApprovedBy\")\n  createdMessages  Message[] @relation(\"MessageCreatedBy\")\n  updatedMessages  Message[] @relation(\"MessageUpdatedBy\")\n\n  // Responses authored by Users\n  responses Response[] @relation(\"UserResponses\")\n\n  // Projects\n  approvedProjects Project[] @relation(\"ProjectApprovedBy\")\n  createdProjects  Project[] @relation(\"ProjectCreatedBy\")\n  updatedProjects  Project[] @relation(\"ProjectUpdatedBy\")\n\n  // Reports\n  approvedReports Report[] @relation(\"ReportApprovedBy\")\n  createdReports  Report[] @relation(\"ReportCreatedBy\")\n  updatedReports  Report[] @relation(\"ReportUpdatedBy\")\n\n  // Podcasts\n  approvedPodcasts Podcast[] @relation(\"PodcastApprovedBy\")\n  createdPodcasts  Podcast[] @relation(\"PodcastCreatedBy\")\n  updatedPodcasts  Podcast[] @relation(\"PodcastUpdatedBy\")\n\n  // Events\n  createdEvents Event[] @relation(\"EventCreatedBy\")\n  updatedEvents Event[] @relation(\"EventUpdatedBy\")\n\n  // Radio Talkshows\n  createdTalkshows  RadioTalkshow[] @relation(\"RadioTalkshowCreatedBy\")\n  updatedTalkshows  RadioTalkshow[] @relation(\"RadioTalkshowUpdatedBy\")\n  approvedTalkshows RadioTalkshow[] @relation(\"RadioTalkshowApprovedBy\")\n  hostedTalkshows   RadioTalkshow[] @relation(\"TalkshowHostUser\")\n  hostedPodcasts    Podcast[]       @relation(\"PodcastHostUser\")\n\n  // Beneficiaries\n  createdBeneficiaries  Beneficiary[] @relation(\"BeneficiaryCreatedBy\")\n  updatedBeneficiaries  Beneficiary[] @relation(\"BeneficiaryUpdatedBy\")\n  approvedBeneficiaries Beneficiary[] @relation(\"BeneficiaryApprovedBy\")\n\n  // Institutions\n  createdInstitutions  Institution[] @relation(\"InstitutionCreatedBy\")\n  updatedInstitutions  Institution[] @relation(\"InstitutionUpdatedBy\")\n  approvedInstitutions Institution[] @relation(\"InstitutionApprovedBy\")\n\n  // FAQs\n  createdFaqs  FAQ[] @relation(\"FAQCreatedBy\")\n  updatedFaqs  FAQ[] @relation(\"FAQUpdatedBy\")\n  approvedFaqs FAQ[] @relation(\"FAQApprovedBy\")\n\n  // Team\n  createdTeamMembers Team[] @relation(\"TeamCreatedBy\")\n  updatedTeamMembers Team[] @relation(\"TeamUpdatedBy\")\n}\n\nmodel PasswordHistory {\n  id           String   @id @default(cuid())\n  user         User     @relation(fields: [userId], references: [id])\n  userId       String\n  passwordHash String\n  createdAt    DateTime @default(now())\n\n  @@index([userId, createdAt])\n}\n\nmodel PasswordChangeLog {\n  id        String   @id @default(cuid())\n  user      User     @relation(fields: [userId], references: [id])\n  userId    String\n  changedBy String? // userId of admin / null if self\n  ip        String?\n  userAgent String?\n  createdAt DateTime @default(now())\n\n  @@index([userId, createdAt])\n}\n\nmodel FailedLoginAttempt {\n  id        String   @id @default(cuid())\n  user      User?    @relation(fields: [userId], references: [id])\n  userId    String?\n  ip        String?\n  createdAt DateTime @default(now())\n\n  @@index([userId, createdAt])\n  @@index([ip, createdAt])\n}\n\nmodel Session {\n  id         String    @id @default(cuid())\n  user       User      @relation(fields: [userId], references: [id])\n  userId     String\n  startedAt  DateTime  @default(now())\n  lastSeenAt DateTime  @default(now())\n  endedAt    DateTime?\n  ip         String?\n  userAgent  String?\n  active     Boolean   @default(true)\n\n  @@index([userId, startedAt])\n  @@index([active])\n}\n\nenum Status {\n  active\n  completed\n  paused\n}\n\nenum PublishStatus {\n  draft\n  published\n}\n\nmodel Event {\n  id               Int      @id @default(autoincrement())\n  slug             String   @unique\n  eventTitle       Json // Tiptap JSON doc (edited/viewed via components/editor/*)\n  eventDescription Json\n  eventDetails     Json?\n  eventLocation    String?\n  eventBanner      String\n  eventImages      String[]\n  eventFile        String\n\n  eventStartDate DateTime\n  eventEndDate   DateTime\n\n  eventTags       String[]\n  eventStatus     EventStatus    @default(pending)\n  publishStatus   PublishStatus  @default(draft)\n  eventAttendance AttendanceType @default(public)\n  maxAttendees    Int?\n\n  accessCount   Int @default(0)\n  downloadCount Int @default(0)\n\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n  deletedAt DateTime?\n\n  createdById String\n  updatedById String\n\n  createdBy User @relation(\"EventCreatedBy\", fields: [createdById], references: [id])\n  updatedBy User @relation(\"EventUpdatedBy\", fields: [updatedById], references: [id])\n\n  projectId Int?\n  project   Project? @relation(fields: [projectId], references: [id])\n\n  reportId      Int?\n  report        Report?            @relation(fields: [reportId], references: [id])\n  beneficiaries BeneficiaryEvent[]\n  talkshows     RadioTalkshow[]\n  podcasts      Podcast[]\n}\n\nenum EventStatus {\n  pending\n  ongoing\n  completed\n  paused\n}\n\nenum AttendanceType {\n  public\n  registration_required\n}\n\n// YouTube Videos\nmodel Youtube {\n  id          String   @id // YouTube video ID\n  title       String\n  description String\n  thumbnail   String\n  publishedAt DateTime\n  viewCount   Int?\n  likeCount   Int?\n  duration    String\n  fetchedAt   DateTime @default(now()) // When this video was last fetched from YouTube\n}\n\nmodel YouTubeCacheMeta {\n  id          Int      @id @default(1)\n  lastFetched DateTime\n}\n\n// Institution Model\nenum InstitutionType {\n  education\n  faith_based_organization\n  local_community\n  ngo\n  government\n  other\n}\n\nenum InstitutionCategory {\n  funding\n  collaborating\n  implementing\n  beneficiary\n}\n\nmodel Institution {\n  id                  String              @id @default(cuid())\n  name                String\n  email               String?             @unique\n  phone               String?             @unique\n  logo                String?\n  institutionImages   String[]\n  headName            String?\n  institutionType     InstitutionType\n  institutionCategory InstitutionCategory @default(implementing)\n  createdAt           DateTime            @default(now())\n  updatedAt           DateTime            @updatedAt\n  locations           Location[]\n  beneficiaries       Beneficiary[]\n  talkshows           RadioTalkshow[]\n  podcasts            Podcast[]\n\n  createdById  String\n  updatedById  String?\n  approvedById String?\n\n  createdBy  User  @relation(\"InstitutionCreatedBy\", fields: [createdById], references: [id])\n  updatedBy  User? @relation(\"InstitutionUpdatedBy\", fields: [updatedById], references: [id])\n  approvedBy User? @relation(\"InstitutionApprovedBy\", fields: [approvedById], references: [id])\n}\n\n// Model for representing a location (name, lat, lng)\nmodel Location {\n  id            String      @id @default(cuid())\n  locationName  String?\n  latitude      Float?\n  longitude     Float?\n  institutionId String\n  institution   Institution @relation(fields: [institutionId], references: [id])\n}\n\n// Beneficiary model\nenum GenderType {\n  male\n  female\n}\n\nmodel Beneficiary {\n  id                String        @id @default(cuid())\n  firstName         String\n  lastName          String\n  image             String?\n  images            String[]\n  gender            GenderType?\n  email             String?       @unique\n  phone             String?       @unique\n  dateOfBirth       DateTime?\n  createdAt         DateTime      @default(now())\n  updatedAt         DateTime      @updatedAt\n  beneficiaryStatus PublishStatus @default(draft)\n\n  // Tiptap JSON doc: an optional first-person testimonial (\"Beneficiary\n  // Voice\"). Shown publicly only when non-empty AND beneficiaryStatus is\n  // 'published' — there is no separate publish flag for the voice itself,\n  // it reuses the record's own beneficiaryStatus.\n  voice Json?\n\n  // unified messages and responses\n  messages  Message[]  @relation(\"BeneficiaryMessages\")\n  responses Response[] @relation(\"BeneficiaryResponses\")\n\n  // A beneficiary belongs to at most one institution, or none at all.\n  institutionId String?\n  institution   Institution? @relation(fields: [institutionId], references: [id])\n\n  // A beneficiary can be linked to any number of projects/events/reports\n  // (e.g. \"beneficiaries who attended this event\").\n  projects  BeneficiaryProject[]\n  events    BeneficiaryEvent[]\n  reports   BeneficiaryReport[]\n  podcasts  BeneficiaryPodcast[]\n  talkshows BeneficiaryTalkshow[]\n\n  // Radio talkshows / podcasts this beneficiary hosted (the \"By\" field, when\n  // hostType = beneficiary) — distinct from `talkshows`/`podcasts` above,\n  // which are the \"participants\" lists.\n  hostedTalkshows RadioTalkshow[] @relation(\"TalkshowHostBeneficiary\")\n  hostedPodcasts  Podcast[]       @relation(\"PodcastHostBeneficiary\")\n\n  createdById  String\n  updatedById  String?\n  approvedById String?\n\n  createdBy  User  @relation(\"BeneficiaryCreatedBy\", fields: [createdById], references: [id])\n  updatedBy  User? @relation(\"BeneficiaryUpdatedBy\", fields: [updatedById], references: [id])\n  approvedBy User? @relation(\"BeneficiaryApprovedBy\", fields: [approvedById], references: [id])\n}\n\n// Join models linking a Beneficiary to the Project/Event/Report they took\n// part in. Kept as explicit models (rather than implicit many-to-many) so a\n// participation record can carry its own metadata later (e.g. a role or\n// attendance date) without another migration.\nmodel BeneficiaryProject {\n  id            String      @id @default(cuid())\n  beneficiaryId String\n  beneficiary   Beneficiary @relation(fields: [beneficiaryId], references: [id], onDelete: Cascade)\n  projectId     Int\n  project       Project     @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  createdAt     DateTime    @default(now())\n\n  @@unique([beneficiaryId, projectId])\n}\n\nmodel BeneficiaryEvent {\n  id            String      @id @default(cuid())\n  beneficiaryId String\n  beneficiary   Beneficiary @relation(fields: [beneficiaryId], references: [id], onDelete: Cascade)\n  eventId       Int\n  event         Event       @relation(fields: [eventId], references: [id], onDelete: Cascade)\n  createdAt     DateTime    @default(now())\n\n  @@unique([beneficiaryId, eventId])\n}\n\nmodel BeneficiaryReport {\n  id            String      @id @default(cuid())\n  beneficiaryId String\n  beneficiary   Beneficiary @relation(fields: [beneficiaryId], references: [id], onDelete: Cascade)\n  reportId      Int\n  report        Report      @relation(fields: [reportId], references: [id], onDelete: Cascade)\n  createdAt     DateTime    @default(now())\n\n  @@unique([beneficiaryId, reportId])\n}\n\nmodel BeneficiaryPodcast {\n  id            String      @id @default(cuid())\n  beneficiaryId String\n  beneficiary   Beneficiary @relation(fields: [beneficiaryId], references: [id], onDelete: Cascade)\n  podcastId     Int\n  podcast       Podcast     @relation(fields: [podcastId], references: [id], onDelete: Cascade)\n  createdAt     DateTime    @default(now())\n\n  @@unique([beneficiaryId, podcastId])\n}\n\nmodel BeneficiaryTalkshow {\n  id            String        @id @default(cuid())\n  beneficiaryId String\n  beneficiary   Beneficiary   @relation(fields: [beneficiaryId], references: [id], onDelete: Cascade)\n  talkshowId    Int\n  talkshow      RadioTalkshow @relation(fields: [talkshowId], references: [id], onDelete: Cascade)\n  createdAt     DateTime      @default(now())\n\n  @@unique([beneficiaryId, talkshowId])\n}\n\n// \"By\" — who hosted/appeared on a talkshow or podcast: an existing\n// beneficiary, an admin (an app User), or a free-text guest name. Exactly\n// one of the corresponding fields is expected to be set, matching hostType\n// — enforced at the application level, same approach as Response.responderType\n// above.\nenum HostType {\n  beneficiary\n  admin\n  guest\n}\n\nmodel RadioTalkshow {\n  id            Int           @id @default(autoincrement())\n  title         String\n  date          DateTime\n  image         String? // illustration / cover artwork (card thumbnail)\n  poster        String? // wide banner used as the /resources page hero when this is the latest published talkshow\n  audioUrl      String? // mp3 path under public/assets/audio/talkshow\n  waveform      Float[]       @default([]) // precomputed amplitude peaks (0..1) for the waveform UI\n  publishStatus PublishStatus @default(draft)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  createdById  String\n  updatedById  String?\n  approvedById String?\n\n  createdBy  User  @relation(\"RadioTalkshowCreatedBy\", fields: [createdById], references: [id])\n  updatedBy  User? @relation(\"RadioTalkshowUpdatedBy\", fields: [updatedById], references: [id])\n  approvedBy User? @relation(\"RadioTalkshowApprovedBy\", fields: [approvedById], references: [id])\n\n  // Optional single links to other content this talkshow relates to.\n  projectId Int?\n  project   Project? @relation(fields: [projectId], references: [id])\n\n  eventId Int?\n  event   Event? @relation(fields: [eventId], references: [id])\n\n  reportId Int?\n  report   Report? @relation(fields: [reportId], references: [id])\n\n  institutionId String?\n  institution   Institution? @relation(fields: [institutionId], references: [id])\n\n  // \"By\": who hosted/appeared — see HostType above.\n  hostType          HostType?\n  hostBeneficiaryId String?\n  hostBeneficiary   Beneficiary? @relation(\"TalkshowHostBeneficiary\", fields: [hostBeneficiaryId], references: [id])\n  hostUserId        String?\n  hostUser          User?        @relation(\"TalkshowHostUser\", fields: [hostUserId], references: [id])\n  hostFirstName     String?\n  hostLastName      String?\n\n  // Beneficiaries who took part as participants.\n  participants BeneficiaryTalkshow[]\n\n  // Podcasts linked to this talkshow (reverse of Podcast.talkshowId — a\n  // podcast episode points at one talkshow; a talkshow can be referenced by\n  // many podcast episodes). Editable from either side.\n  podcasts Podcast[]\n}\n\n/**\n * ResponderType: external removed so visitors cannot author Responses.\n * Use application-level checks to ensure only users/beneficiaries/system create responses.\n */\nenum ResponderType {\n  user\n  beneficiary\n  system\n}\n\nmodel Response {\n  id            String        @id @default(cuid())\n  messageId     Int\n  responderType ResponderType @default(user)\n\n  // polymorphic responder fields (only one should be set; enforce at application level)\n  responderUserId        String?\n  responderBeneficiaryId String?\n\n  content Json\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // relations\n  message              Message      @relation(fields: [messageId], references: [id])\n  responderUser        User?        @relation(\"UserResponses\", fields: [responderUserId], references: [id])\n  responderBeneficiary Beneficiary? @relation(\"BeneficiaryResponses\", fields: [responderBeneficiaryId], references: [id])\n}\n\nmodel FAQ {\n  id            Int           @id @default(autoincrement())\n  question      Json\n  answer        Json\n  category      FAQCategory   @default(general)\n  publishStatus PublishStatus @default(draft)\n  createdAt     DateTime      @default(now())\n  updatedAt     DateTime      @updatedAt\n\n  createdById  String\n  updatedById  String\n  approvedById String\n\n  createdBy  User @relation(\"FAQCreatedBy\", fields: [createdById], references: [id])\n  updatedBy  User @relation(\"FAQUpdatedBy\", fields: [updatedById], references: [id])\n  approvedBy User @relation(\"FAQApprovedBy\", fields: [approvedById], references: [id])\n}\n\nenum FAQCategory {\n  general\n  beneficiaries\n  institutions\n  projects\n  events\n  reports\n  technnology\n  other\n}\n\n// #Facebook Posts\nmodel FacebookPost {\n  id           String   @id // Facebook post ID\n  message      String?\n  createdTime  DateTime\n  permalinkUrl String\n  fullPicture  String\n  fetchedAt    DateTime @default(now())\n}\n\nmodel FacebookCacheMeta {\n  id          Int      @id @default(1)\n  lastFetched DateTime\n}\n\nenum TeamRole {\n  founder\n  co_founder\n  board_member\n  project_director\n  program_director\n  project_manager\n  coordinator\n  mentor\n  volunteer\n  advisor\n  communications\n  finance\n  operations\n  web_developer\n  web_maintainer\n  other\n}\n\nmodel Team {\n  id Int @id @default(autoincrement())\n\n  firstName    String\n  lastName     String\n  profileImage String?\n  about        String?\n\n  // contact & social\n  email       String? @unique\n  phone       String? @unique\n  linkedInUrl String?\n  facebookUrl String?\n  xUrl        String?\n  websiteUrl  String?\n\n  // status\n  isActive Boolean @default(true)\n\n  // audit\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  createdById String\n  updatedById String?\n\n  createdBy User  @relation(\"TeamCreatedBy\", fields: [createdById], references: [id])\n  updatedBy User? @relation(\"TeamUpdatedBy\", fields: [updatedById], references: [id])\n}\n"
}

